/** Codes use 6 characters without look-alikes (no 0/O, 1/I/L), as generated by the API. */
const INVITATION_CODE_PATTERN = /^[ABCDEFGHJKMNPQRSTUVWXYZ23456789]{6}$/;

/** Uppercases and drops spaces and dashes, so " abc-234 " becomes "ABC234". */
export function normalizeInvitationCode(input: string): string {
  return input.toUpperCase().replace(/[\s-]/g, '');
}

export function isValidInvitationCode(code: string): boolean {
  return INVITATION_CODE_PATTERN.test(code);
}
